import itertools,re
from probe_lib import *
fam='cursor-counter'
seed=(OUT/'paint-cursor-object-result-inplace-life.cpp').read_text()
for receiver,order,kind in itertools.product(['i','value','dim','copyvalue','copydim'],['normal','reverse'],['int','long']):
 s=seed
 if receiver in ['value','dim']:
  s=s.replace('int i;','');s=re.sub(r'\bi\b',receiver,s)
 elif receiver=='copyvalue':s=s.replace('unsigned int hi = (unsigned short)(value+10);','int i=value;\nunsigned int hi = (unsigned short)(i+10);').replace('hi=w>>16;\nint i;','hi=w>>16;')
 elif receiver=='copydim':s=s.replace('unsigned int hi = (unsigned short)(value+10);','int i=dim;\nunsigned int hi = (unsigned short)(value+10);').replace('if(dim != 0)','if(i != 0)').replace('hi=w>>16;\nint i;','hi=w>>16;')
 else:s=s.replace('unsigned int hi = (unsigned short)(value+10);','int i;\nunsigned int hi = (unsigned short)(value+10);').replace('hi=w>>16;\nint i;','hi=w>>16;')
 if order=='reverse':s=s.replace('Paint(int value, int dim)','Paint(int dim, int value)').replace('cursor.Paint(a, dim)','cursor.Paint(dim, a)')
 if kind=='long':
  if receiver in ['value','dim']:s=s.replace('int '+receiver+',','long '+receiver+',').replace('int '+receiver+')','long '+receiver+')')
  else:s=s.replace('int i','long i')
 test('cursor-counter-'+receiver+'-'+order+'-'+kind,s,fam)
report(fam)

scripts.dim_probe.py:
import itertools
from probe_lib import *
fam='dim-layout'
clean='//cpp\n'+BASE[BASE.rindex('#pragma opt_lifetimes off'):]
old='''    hi = angle;
    if (dim != 0)
        hi = (unsigned short)(hi - 4);
    p = bg + m;
    w = hi << 0x1c;
    hi = w >> 16;'''
forms={
'pointer-each-arm':'''    hi = angle;
    if(dim != 0) { hi = (unsigned short)(hi-4); p=bg+m; }
    else { p=bg+m; }
    w=hi<<28; hi=w>>16;''',
'shift-each-arm':'''    hi = angle;
    if(dim != 0) { hi = (unsigned short)(hi-4); w=hi<<28; }
    else { w=hi<<28; }
    p=bg+m; hi=w>>16;''',
'shift-pointer-each-arm':'''    hi = angle;
    if(dim != 0) { hi = (unsigned short)(hi-4); w=hi<<28; p=bg+m; }
    else { w=hi<<28; p=bg+m; }
    hi=w>>16;''',
'zero-first':'''    if(dim == 0) { hi=angle; p=bg+m; }
    else { hi=(unsigned short)(angle-4); p=bg+m; }
    w=hi<<28; hi=w>>16;''',
'goto-dim-first':'''    hi=angle;
    if(dim == 0) goto normal;
    hi=(unsigned short)(hi-4);
    p=bg+m;
    goto shifted;
normal:
    p=bg+m;
shifted:
    w=hi<<28; hi=w>>16;''',
'goto-paint-first':'''    hi=angle;
    if(dim != 0) goto dimmed;
    goto normal;
dimmed:
    hi=(unsigned short)(hi-4);
normal:
    p=bg+m; w=hi<<28; hi=w>>16;''',
'early-pointer-else':'''    hi=angle;
    p=bg+m;
    if(dim == 0) { w=hi<<28; }
    else { hi=(unsigned short)(hi-4); w=hi<<28; }
    hi=w>>16;''',
'do-break':'''    hi=angle;
    do { if(dim == 0) { p=bg+m; break; }
         hi=(unsigned short)(hi-4); p=bg+m; } while(0);
    w=hi<<28; hi=w>>16;''',
'switch-dim':'''    hi=angle;
    switch(dim != 0) { case 0: p=bg+m; break;
    default: hi=(unsigned short)(hi-4); p=bg+m; break; }
    w=hi<<28; hi=w>>16;''',
'branch-palette-last':'''    hi=angle;
    if(dim == 0) { w=hi<<28; hi=w>>16; }
    else { hi=(unsigned short)(hi-4); w=hi<<28; hi=w>>16; }
    p=bg+m;'''
}
for (name,repl),pragma in itertools.product(forms.items(),['life','cse','default']):
 s=clean.replace(old,repl).replace('#pragma opt_lifetimes off',{'life':'#pragma opt_lifetimes off','cse':'#pragma opt_common_subs off','default':''}[pragma]);assert old not in s
 test('dim-'+name+'-'+pragma,s,fam)
# Physical loop placement: do-loop and explicit preheader labels preserve all 24 writes.
for entry,pragma in itertools.product(['goto','do','loop-in-arm'],['life','default']):
 s=clean.replace('#pragma opt_lifetimes off','#pragma opt_lifetimes off' if pragma=='life' else '')
 if entry=='goto':s=s.replace('    for (i = 0; i < 0x18; i++) {','    i=0; goto loop;\nloop:\n    {').replace('        p++;\n    }','        p++;\n        if(++i < 0x18) goto loop;\n    }')
 if entry=='do':s=s.replace('    for (i = 0; i < 0x18; i++) {','    i=0; do {').replace('        p++;\n    }','        p++;\n    } while(++i < 0x18);')
 if entry=='loop-in-arm':
  # Both paths compute same palette, sharing a common paint join after distinct dim arms.
  s=s.replace(old,forms['branch-palette-last']).replace('    for (i = 0; i < 0x18; i++) {','    i=0; do {').replace('        p++;\n    }','        p++;\n    } while(++i < 0x18);')
 test('loop-'+entry+'-'+pragma,s,fam)
report(fam)

scripts.member_state_probe.py:
import itertools,re
from probe_lib import *
fam='cursor-member-state'
seed=(OUT/'paint-cursor-object-result-inplace-life.cpp').read_text()
for fields,reverse,pragma in itertools.product([['i'],['hi'],['w'],['i','hi'],['i','w'],['hi','w'],['i','hi','w']],[False,True],['life','default']):
 s=seed;members={'i':'int i;','hi':'unsigned int hi;','w':'unsigned int w;'}
 fieldlist=['unsigned short *p;']+[members[f] for f in fields]
 if reverse:fieldlist.reverse()
 s=s.replace('unsigned short *p; void Paint',' '.join(fieldlist)+' void Paint')
 if 'hi' in fields:s=s.replace('unsigned int hi =','hi =')
 if 'w' in fields:s=s.replace('unsigned int w=','w=')
 if 'i' in fields:
  # Remove the Paint local only; leave the new field declaration.
  s=s.replace('hi=w>>16;\nint i;','hi=w>>16;')
 s=s.replace('#pragma opt_lifetimes off','#pragma opt_lifetimes off' if pragma=='life' else '')
 test('cursor-fields-'+''.join(fields)+'-'+str(reverse)+'-'+pragma,s,fam)
report(fam)

scripts.native_cursor_probe.py:
import itertools
from probe_lib import *
fam='cursor-native-narrow'
clean='//cpp\n'+BASE[BASE.rindex('#pragma opt_lifetimes off'):]
old='''    angle = (unsigned short)(a + 0xa);
    hi = angle;
    if (dim != 0)
        hi = (unsigned short)(hi - 4);
    p = bg + m;
    w = hi << 0x1c;
    hi = w >> 16;'''
for placement,late,pragma in itertools.product(['pointer-first','palette-first'],['separate','same'],['life','cse','default']):
 decl='struct BorderCursor { '+('unsigned short *p; unsigned short palette;' if placement=='pointer-first' else 'unsigned short palette; unsigned short *p;')+' };\n'
 s=clean.replace('extern "C" void func_ov075',decl+'extern "C" void func_ov075')
 s=s.replace('    unsigned short *p;','    BorderCursor cursor;')
 s=s.replace(old,'''    cursor.palette = a + 0xa;
    if(dim != 0) cursor.palette -= 4;
    cursor.p = bg + m;
    w = (unsigned int)cursor.palette << 28;
    '''+('hi = w >> 16;' if late=='separate' else 'cursor.palette = w >> 16;'))
 for off in ['0x20','0x40','0x37','0x57','0','0x60']:s=s.replace('p['+off+']','cursor.p['+off+']')
 s=s.replace('p++;','cursor.p++;')
 if late=='same':s=s.replace('| hi','| cursor.palette')
 s=s.replace('#pragma opt_lifetimes off',{'life':'#pragma opt_lifetimes off','cse':'#pragma opt_common_subs off','default':''}[pragma])
 test('native-cursor-'+placement+'-'+late+'-'+pragma,s,fam)
report(fam)

scripts.whole_reuse_probe.py:
import itertools,re
from probe_lib import *
fam='whole-cursor-reuse'
for placement,receiver,mode in itertools.product(['before-palette','after-palette','between-dim-shift'],['t','m','slot','count','value','dim'],['plain','copy-before']):
 seed=(OUT/('whole-cursor-'+placement+'-single-life.cpp')).read_text();s=seed
 if mode=='plain':s=s.replace('hi=w>>16;\nint i;','hi=w>>16;');s=re.sub(r'\bi\b',receiver,s)
 else:
  # The old scalar supplies a real input to the palette or address calculation, then serves as counter.
  if receiver not in ['count','value','slot','dim']:continue
  s=s.replace('hi=w>>16;\nint i;','hi=w>>16;')
  s=s.replace('int value, int dim) { ', 'int value, int dim) { int i='+receiver+';\n',1)
  if receiver=='count':s=s.replace('int t=4-count;','int t=4-i;')
  elif receiver=='slot':s=s.replace('int m=slot*','int m=i*')
  elif receiver=='value':s=s.replace('(value+10)','(i+10)')
  else:s=s.replace('if(dim != 0)','if(i != 0)')
 test('whole-reuse-'+placement+'-'+receiver+'-'+mode,s,fam)
report(fam)

